package com.br.edu.iff.rachaconta.webproject.controller;
import com.br.edu.iff.rachaconta.webproject.dto.MoradorDTO;import com.br.edu.iff.rachaconta.webproject.service.*;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.*;import java.util.*;
@Controller @RequestMapping("/moradores") public class MoradoresController{private final MoradorService service;private final CasaService casas;public MoradoresController(MoradorService s,CasaService c){service=s;casas=c;}@GetMapping public String lista(Model m){m.addAttribute("moradores",service.listar());return "moradores/lista";}@GetMapping("/novo")public String novo(Model m){m.addAttribute("morador",new MoradorDTO("","",true,null));m.addAttribute("casas",casas.listar());m.addAttribute("acao","/moradores");return "moradores/form";}@PostMapping public String criar(@RequestParam String nome,@RequestParam String email,@RequestParam(defaultValue="false") boolean ativo,@RequestParam(required=false) Long casaId){service.salvar(new MoradorDTO(nome,email,ativo,casaId));return "redirect:/moradores";}@GetMapping("/{id}")public String detalhe(@PathVariable Long id,Model m){m.addAttribute("morador",service.buscar(id));return "moradores/detalhe";}@GetMapping("/{id}/editar")public String editar(@PathVariable Long id,Model m){var x=service.buscar(id);m.addAttribute("morador",x);m.addAttribute("casas",casas.listar());return "moradores/editar";}@PostMapping("/{id}")public String atualizar(@PathVariable Long id,@RequestParam String nome,@RequestParam String email,@RequestParam(defaultValue="false") boolean ativo,@RequestParam(required=false) Long casaId){service.atualizar(id,new MoradorDTO(nome,email,ativo,casaId));return "redirect:/moradores";}@PostMapping("/{id}/excluir")public String excluir(@PathVariable Long id){service.excluir(id);return "redirect:/moradores";}}
